"""Populate the report from real run artifacts; absent results stay NOT RUN."""
import argparse,json
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--run',default='checkpoints/baseline_v1');p.add_argument('--output',default='FINAL_PROJECT_REPORT.md');a=p.parse_args();root=Path(__file__).resolve().parents[1];run=Path(a.run)
if not run.is_absolute():run=root/run

def read(name):
 f=run/name
 return json.loads(f.read_text()) if f.exists() else None
training=read('training_report.json');threshold=read('threshold.json');result=read('test/metrics.json');errors=read('test/error_analysis_report.json')
sections=[('Abstract','DeepSVerify implements offline reference/query signature verification using a shared Siamese ResNet-18. Baseline results are reported only after training and held-out evaluation.'),('Introduction','Offline verification compares static signature images without pen trajectory or pressure data.'),('Problem statement','Determine whether a query signature is genuine relative to a genuine reference from the claimed writer.'),('Objectives','Preserve verified data preparation; train reproducibly; select a threshold on validation; evaluate held-out writers; provide Windows inference.'),('Dataset','Saved project statistics and the independently inspected image split map contain 16,680 images, 315 writers, 7,560 genuine and 9,120 forgery images: CEDAR, BHSig260 Bengali and Hindi.'),('Data preparation','Existing metadata and duplicate audit are preserved. Hindi writer 123 has no genuine images and remains in train but cannot form pairs. Writer 124 has 48 genuine images, retained as recorded.'),('Preprocessing','Existing preprocessing is reused: grayscale with alpha compositing, Otsu foreground bounding box, 10% margin, background flattening, aspect-preserving resize/pad to 384×128; tensor scaling /255. Resume cache bug fixed by checking stored margin and intensity.'),('Data splitting','Existing writer-disjoint assignments: 221 train writers, 47 validation, 47 test; 11,700 / 2,490 / 2,490 images. No split regeneration.'),('Pair construction','Saved pair QC reports 174,034 pairs, 87,017 per class. Train 122,462; validation 25,804; test 25,768. Validation and test CSVs were independently checked against the image split map during takeover. Full training CSV transfer was blocked here; Colab checks it before training.'),('Proposed architecture','One shared grayscale ResNet-18; global average pooling gives 512 dimensions. Euclidean distance; prediction genuine when distance ≤ frozen threshold. Measured parameter count: 11,170,240.'),('Training methodology','Baseline starts without pretrained weights, no augmentation, no embedding normalization, contrastive margin 1.0, Adam learning rate 0.0001, batch 32, seed 42, planned 10 epochs. Minimum validation loss selects best checkpoint. Epoch-boundary resume restores optimizer and RNG states.'),('Threshold methodology','Choose nearest empirical FAR/FRR crossing on validation only. Freeze threshold with best-checkpoint SHA-256 before test. Test EER is a diagnostic ROC summary; it never changes the deployed threshold.'),('Experimental setup',json.dumps(read('environment.json'),indent=2) if read('environment.json') else 'Full baseline environment: NOT RUN. CPU smoke and test environment is recorded in reports/takeover_20261008/phase4_model_report.json.'),('Results',json.dumps(result['overall'],indent=2) if result else 'NOT RUN — no baseline accuracy, FAR, FRR, EER or AUC available. Real-image smoke: three optimizer steps, checkpoint reload verified; not an evaluation.'),('Dataset-wise results',json.dumps(result['datasets'],indent=2) if result else 'NOT RUN — CEDAR, Bengali, Hindi metrics will be populated from untouched test pairs.'),('Error analysis',json.dumps(errors,indent=2) if errors else 'NOT RUN — evaluator saves pair IDs, writers, dataset, image paths, distances, thresholds, predictions, ground truth and false acceptance/rejection examples.'),('Ablation studies','NOT RUN. Optional after baseline: pretrained weights, embedding normalization or a changed margin in a separate run. No optional experiments are claimed.'),('Limitations','No full baseline trained in this runtime. No GPU available. Only four real preprocessed training images were transferred for smoke testing. 34 perceptual-hash groups cross splits in existing reports; these are possible similarities/collisions, not automatically proven leakage. Full image hash/quality QC has not been rerun. Windows execution and trained-model upload flow still require final user-environment verification. Pair accuracy does not establish real-world fraud detection reliability.'),('Future work','Complete baseline training, validation calibration and held-out evaluation; inspect actual failures; only then consider small ablations or additional acquisition conditions.'),('Conclusion','Software implementation and tests are available. Submission readiness remains conditional on real baseline training, frozen validation threshold, held-out results, and a final local demonstration.')]
text='# DeepSVerify — Final Project Report\n\nStatus: '+('MEASURED baseline results available.' if result else 'IMPLEMENTATION TESTED; BASELINE TRAINING AND FINAL EVALUATION NOT RUN.')+'\n\n'
for i,(title,body) in enumerate(sections,1):text+=f'## {i}. {title}\n\n{body}\n\n'
out=Path(a.output);out=out if out.is_absolute() else root/out
if out.exists():
 old=out.with_suffix('.previous.md')
 if not old.exists():old.write_bytes(out.read_bytes())
out.write_text(text,encoding='utf8');print(out)
